import networkx as nx

def find_workflow_tasks(wb_dsl, target_task_name):
    G = nx.DiGraph()
    # Assuming wb_dsl is a list of tuples (task_name, dependencies)
    for task, dependencies in wb_dsl:
        G.add_node(task)
        for dep in dependencies:
            G.add_edge(dep, task)
    return list(nx.topological_sort(G)) if target_task_name in G else None
